export const getGetMonthlyStatusUrl = (params?: GetMonthlyStatusParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/data-center/monthly-status?${stringifiedParams}` : `/api/data-center/monthly-status`
}

